 private Long id; private String name; private String examType; private Integer sourceYear; private String source; private String usageType; private Integer durationMinutes; private BigDecimal totalScore; private String status; private LocalDateTime createTime; private List<MockPaperSection> sections=new ArrayList<>();
 public Long getId(){return id;} public void setId(Long v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getExamType(){return examType;} public void setExamType(String v){examType=v;} public Integer getSourceYear(){return sourceYear;} public void setSourceYear(Integer v){sourceYear=v;} public String getSource(){return source;} public void setSource(String v){source=v;} public String getUsageType(){return usageType;} public void setUsageType(String v){usageType=v;} public Integer getDurationMinutes(){return durationMinutes;} public void setDurationMinutes(Integer v){durationMinutes=v;} public BigDecimal getTotalScore(){return totalScore;} public void setTotalScore(BigDecimal v){totalScore=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreateTime(){return createTime;} public void setCreateTime(LocalDateTime v){createTime=v;} public List<MockPaperSection> getSections(){return sections;} public void setSections(List<MockPaperSection> v){sections=v;}
